DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT122-S2-Q1$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S2-Q1'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT122-S2-Q1$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Ilana's Position$batch07$, $batch07$Carver's stories are somber and pessimistic, and that is "a sure sign of inferior writing".$batch07$), (1, $batch07$Gustav's Position$batch07$, $batch07$Carver was one of the finest writers in 30 years. Yes, his stories are somber and pessimistic, but they are also humorous, compassionate, and beautifully structured.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$They agree on the facts: the stories are somber and pessimistic. The fight is over what that means. Ilana's "sure sign" is a conditional: somber means inferior. Gustav refutes it with a counterexample: Carver is somber *and* one of the finest writers.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether well-written stories can be somber and pessimistic.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT122-S2-Q1$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$Gustav says the stories are compassionate. Ilana never talks about compassion.$batch07$), ($batch07$B$batch07$, $batch07$Ilana calls them pessimistic, and Gustav says "Granted".$batch07$), ($batch07$C$batch07$, $batch07$Gustav says Carver's somber stories are also wryly humorous. Ilana never discusses humor.$batch07$), ($batch07$D$batch07$, $batch07$Ilana: somber and pessimistic is a "sure sign of inferior writing", so good writing can't be somber. Gustav: Carver's somber stories are fine writing.$batch07$), ($batch07$E$batch07$, $batch07$Ilana treats somberness as decisive. Gustav weighs several features, but Gustav never says *no* feature can be decisive. We can't put Gustav on the other side.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT122-S2-Q1$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
